    "id": "N3.4",
    "filename": "n3.4-overcoming-envy-status-games.md",
    "author": "Naval Ravikant",
    "knowledge_base": "Naval Ravikant",
    "title": "Overcoming Envy, Social Comparison & Status Games",
    "slug": "overcoming-envy-social-comparison-status-games",
